function generationElapsed(){var job=workshop.job;if(job&&typeof job.elapsed_seconds==='number')return Math.floor(job.elapsed_seconds);if(job&&typeof job.elapsed==='number')return Math.floor(job.elapsed);var base=workshop.startedAt;if(job&&typeof job.created_at==='number')base=job.created_at>1000000000000?job.created_at:job.created_at*1000;else if(job&&typeof job.created_at==='string'){var parsed=Date.parse(job.created_at);if(isFinite(parsed))base=parsed;}return base?Math.max(0,Math.floor(((workshop.finishedAt||Date.now())-base)/1000)):0;}
function receivedChars(){return workshop.job&&typeof workshop.job.received_chars==='number'?Math.max(0,Math.floor(workshop.job.received_chars)):0;}
function generationTitle(){return {submitting:'正在提交任务',restoring:'正在确认上次任务',queued:'任务已排队',generating:'正在生成应用',checking:'正在检查应用',ready:workshop.installed?'应用已安装':'生成完成',failed:'生成失败',installing:'正在安装到桌面'}[generationState()]||'';}
function generationDetail(){var job=workshop.job,state=generationState();if(workshop.pollFailures)return '连接暂时中断，正在重新连接；任务不会因离开页面而取消。';if(state==='restoring')return '正在查询上次任务的实际状态。';if(state==='failed')return safeJobError(job&&job.error||workshop.message);if(state==='ready')return workshop.installed?'返回桌面即可打开。':'先体验下方预览，满意后安装到桌面。';if(state==='installing')return '正在保存应用，请稍候。';return job&&job.progress_text||'完成后先预览，由你确认安装。';}
function workshopProgressHtml(){if(!workshop.startedAt&&!workshop.job&&!workshop.busy)return '';var state=generationState(),busy=['submitting','restoring','queued','generating','checking','installing'].indexOf(state)>=0;return '<section id="workshop-progress" class="generation-progress '+(state==='failed'?'failed':'')+'" aria-label="应用生成状态"><div class="generation-status"><span id="generation-spinner" class="generation-spinner" aria-hidden="true" '+(!busy?'hidden':'')+'></span><strong id="generation-title" aria-live="polite">'+esc(generationTitle())+'</strong><span id="generation-elapsed">'+generationElapsed()+' 秒</span></div><div id="generation-rail" class="generation-rail" aria-hidden="true" '+(!busy?'hidden':'')+'><span></span></div><ol class="generation-stages">'+['queued','generating','checking','ready'].map(function(k,i){return '<li data-generation-stage="'+k+'">'+['排队','生成','检查','完成'][i]+'</li>';}).join('')+'</ol><p id="generation-detail">'+esc(generationDetail())+'</p><p id="generation-chars" class="generation-meta" '+(!receivedChars()?'hidden':'')+'>已接收 '+receivedChars().toLocaleString('zh-CN')+' 字符</p>'+(state==='failed'?'<button id="workshop-retry">重试生成</button>':'')+'</section>';}
function updateWorkshopProgress(){var region=document.getElementById('workshop-progress');if(!region)return;var state=generationState(),busy=['submitting','restoring','queued','generating','checking','installing'].indexOf(state)>=0;var title=document.getElementById('generation-title'),elapsed=document.getElementById('generation-elapsed'),detail=document.getElementById('generation-detail'),spinner=document.getElementById('generation-spinner'),rail=document.getElementById('generation-rail');if(title&&title.textContent!==generationTitle())title.textContent=generationTitle();if(elapsed)elapsed.textContent=generationElapsed()+' 秒';if(detail&&detail.textContent!==generationDetail())detail.textContent=generationDetail();var chars=document.getElementById('generation-chars');if(chars){chars.hidden=receivedChars()===0;chars.textContent='已接收 '+receivedChars().toLocaleString('zh-CN')+' 字符';}if(spinner)spinner.hidden=!busy;if(rail)rail.hidden=!busy;region.classList.toggle('failed',state==='failed');var index=['queued','generating','checking','ready'].indexOf(state);region.querySelectorAll('[data-generation-stage]').forEach(function(e,i){e.classList.toggle('active',i===index);e.classList.toggle('complete',i<index);});}
function workshopHtml(){var job=workshop.job,ready=job&&job.status==='ready'&&job.bundle,voice=workshop.voice,recording=voice&&voice.recording;if(workshop.busy)return '<div class="page-heading"><h1>工作坊</h1></div><div class="progress-screen">'+companionHtml('thinking')+workshopProgressHtml()+'</div>';if(workshop.page==='voice')return voiceHtml();if(workshop.page==='speak')return speechHtml();if(workshop.page==='model'||workshop.page==='stt'||workshop.page==='tts')return configHtml();if(ready&&workshop.page==='celebrate')return '<div class="flow-screen">'+companionHtml('success')+'<h1>做好了，来试试</h1><p>接下来是全屏预览</p></div>';if(ready&&workshop.page==='preview'){main.className='app-frame';return appFrameHtml('生成应用全屏预览','',true);}if(ready&&workshop.page==='installed')return '<div class="flow-screen">'+companionHtml('success')+'<h1>'+esc(job.bundle.manifest.name)+'</h1><p>已放到桌面最后 · 随时可以打开</p><p class="subtitle">应用市场「我的」可以继续修改、上传首页截图并分享。</p><div class="workshop-actions"><button data-app="'+esc(job.bundle.manifest.id)+'" class="primary">打开应用</button><button id="workshop-cloud">保存到我的作品</button><button id="workshop-new">再做一个</button></div></div>';if(ready&&workshop.page==='result')return '<div class="page-heading"><h1>'+esc(job.bundle.manifest.name)+'</h1></div>'+companionHtml(workshop.error?'error':'success','small')+'<p class="result-detail">预览数据仅用于体验，安装后可保存在设备。<br>保存到「我的作品」，两端都能继续修改和分享。</p><div class="workshop-actions"><button data-workshop-page="preview">全屏预览</button><button id="workshop-install" class="primary" '+(workshop.installed?'disabled':'')+'>'+(workshop.installed?'已安装':'安装到桌面')+'</button></div><button id="workshop-regenerate">修改需求</button><button id="workshop-cloud">保存到我的作品</button><p id="workshop-feedback" class="feedback '+(workshop.error?'error':'')+'">'+esc(workshop.message)+'</p>';if(job&&job.status==='failed'&&workshop.page==='failure')return '<div class="flow-screen">'+companionHtml('error')+'<h1>这次没做好</h1><p class="flow-detail atom-scroll">'+esc(safeJobError(job.error))+'</p><div class="workshop-actions"><button id="workshop-retry" class="primary">再试一次</button><button data-workshop-page="input">修改需求 / 配置</button></div></div>';return '<div class="page-heading"><h1>工作坊</h1><button id="workshop-config">模型配置</button></div><label class="form-field"><span>想做什么应用？</span><textarea id="workshop-prompt" maxlength="4000" placeholder="例如：一个能记录每日喝水次数的小工具">'+esc(workshop.prompt)+'</textarea></label><div class="workshop-actions"><button id="voice-toggle" '+(workshop.voiceBusy?'disabled':'')+'>'+ (workshop.pendingRecordingId?'转写录音':'说出想法')+'</button><select id="workshop-theme" aria-label="生成应用的主题">'+themeLibrary.themes.map(function(t){return '<option value="'+esc(t.id)+'" '+(t.id===workshop.theme_id?'selected':'')+'>'+esc(t.name)+'</option>';}).join('')+'</select>'+workshopAction()+'</div><p class="subtitle voice-note">'+esc(workshopNote())+'</p><p id="workshop-feedback" class="feedback '+(workshop.error?'error':'')+'">'+esc(workshop.message)+'</p>';}
function updateRecordingIndicator(){var e=document.getElementById('recording-indicator');if(e)e.hidden=!(workshop.voice&&workshop.voice.recording);}
// Own key first; otherwise the ATOM official quota for a signed-in account.
function workshopOfficial(){var c=workshop.config;return c&&!c.api_key_set&&c.official||null;}
function workshopAction(){var c=workshop.config,o=workshopOfficial();if(!c||c.api_key_set||o&&o.active)return '<button id="workshop-generate" class="primary">生成</button>';if(o&&o.reason==='sign_in')return '<button id="workshop-login" class="primary">登录后生成</button>';return '<button id="workshop-setup" class="primary">先设置模型</button>';}
function workshopNote(){var c=workshop.config,o=workshopOfficial();if(!c)return '正在读取模型配置…';if(o&&o.active)return '使用 ATOM 官方额度 · 本月还可生成 '+o.remaining+' 次';if(o&&o.reason==='sign_in')return '登录 ATOM 账号就能用官方额度，每月 '+(o.limit||30)+' 次；也可以填写自己的模型 Key';if(!c.api_key_set)return o&&o.error?o.error:'还没有设置模型 API Key，设置后才能生成应用';return workshop.voice&&workshop.voice.stt_configured?'先预览，再安装 · 草稿自动保存':'可以用文字生成 · 语音输入需在模型配置中设置';}
function loadWorkshop(){var revision=workshop.voiceRevision;loadThemes();request('/api/model-config').then(function(c){workshop.config=c;if(!workshop.modelTouched){workshop.draft={provider:c.provider||'custom',base_url:c.base_url||'',model:c.model||'',protocol:c.protocol||'openai',stt_base_url:c.stt_base_url||'',stt_model:c.stt_model||'',tts_base_url:c.tts_base_url||'',tts_model:c.tts_model||'',tts_voice:c.tts_voice||'tongtong'};}if(view==='workshop'&&['input','model','stt','tts'].indexOf(workshop.page)>=0)render();}).catch(function(e){workshop.message=e.message;workshop.error=true;if(view==='workshop'&&['input','model','stt','tts'].indexOf(workshop.page)>=0)render();});request('/api/voice/status').then(function(v){if(revision!==workshop.voiceRevision||workshop.voiceBusy)return;workshop.voice=v;updateRecordingIndicator();if(view==='workshop'&&['input','model','stt','tts'].indexOf(workshop.page)>=0)render();}).catch(function(e){workshop.voice={available:false,recording:false,reason:e.message};if(view==='workshop'&&['input','model','stt','tts'].indexOf(workshop.page)>=0)render();});}
function saveModel(){var data={};['provider','base_url','model','protocol','stt_base_url','stt_model','tts_base_url','tts_model','tts_voice'].forEach(function(k){if(workshop.draft[k]!==undefined)data[k]=workshop.draft[k];});['api_key','stt_api_key','tts_api_key'].forEach(function(k){if(workshop.draft[k])data[k]=workshop.draft[k];});post('/api/model-config',data).then(function(c){workshop.config=c;workshop.draft.api_key='';workshop.draft.stt_api_key='';workshop.draft.tts_api_key='';workshop.message='配置已保存';workshop.error=false;workshop.modelTouched=false;if(view==='workshop'){render();feedback('model-feedback','配置已保存');}}).catch(function(e){feedback('model-feedback',e.message,true);});}
function returnKeyRelay(){return '<script src="/home-key.js"><\/script>';}

function hydrateReturnKeys(frame,entry){/* Installed HTML receives the trusted relay from the local server; do not execute applications twice. */}
function previewThemeHtml(bundle){if(bundle.manifest&&bundle.manifest.theme_mode==='fixed')return '';var id=themeLibrary.active&&typeof themeLibrary.active==='object'?themeLibrary.active.id:themeLibrary.active,theme=themeLibrary.themes.find(function(t){return t.id===id;});if(!theme)return '';var css=Object.keys(theme.tokens).map(function(k){return '--'+k+':'+theme.tokens[k];}).join(';');var aliases={paper:'bg',bg:'bg',ink:'ink',card:'card',accent:'accent',action:'action',muted:'muted','secondary-text':'muted',line:'line'};Object.keys(aliases).forEach(function(k){css+=';--atom-'+k+':'+theme.tokens[aliases[k]];});css+=';--accent-ink:'+(id==='system-dark'?'#08111e':'#ffffff')+';--atom-color-scheme:'+(id==='system-dark'?'dark':'light')+';color-scheme:'+(id==='system-dark'?'dark':'light');return '<style data-atom-preview-theme>:root{'+css+'}</style>';}
function previewHtml(bundle){var files=bundle.files||{},html=files['index.html']||'<p>没有可预览的入口。</p>';html=html.replace(/<link\b[^>]*href=["']([^"']+)["'][^>]*>/gi,function(tag,path){var name=path.replace(/^\.\//,'');return files[name]!==undefined&&/\.css$/i.test(name)?'<style>'+files[name]+'</style>':tag;});html=html.replace(/<script\b[^>]*src=["']([^"']+)["'][^>]*>\s*<\/script>/gi,function(tag,path){var name=path.replace(/^\.\//,'');return files[name]!==undefined?'<script>'+files[name]+'<\/script>':tag;});var runtime='<script src="/input-navigation.js"><\/script><script src="/app-runtime.js"><\/script>';html=/<head\b[^>]*>/i.test(html)?html.replace(/<head\b[^>]*>/i,function(tag){return tag+runtime;}):runtime+html;var appearance='<link rel="stylesheet" href="/'+(bundle.manifest&&bundle.manifest.theme_ui==='controls'?'theme-controls.css':'app-appearance.css')+'">';html=html.indexOf('</head>')>=0?html.replace('</head>',appearance+'</head>'):appearance+html;var palette=previewThemeHtml(bundle);html=html.indexOf('</head>')>=0?html.replace('</head>',palette+'</head>'):palette+html;return html+returnKeyRelay();}
function safeJobError(error){if(typeof error==='string')return error;if(error&&typeof error.message==='string')return error.message;return '生成失败，请检查模型配置后重试。';}
function startGeneration(){var prompt=workshop.prompt.trim();if(!prompt){workshop.message='先描述你想做的应用';workshop.error=true;render();return;}if(workshop.busy)return;clearTimeout(workshop.poll);workshop.busy=true;workshop.page='busy';workshop.voicePhase=null;workshop.installed=false;workshop.pollFailures=0;workshop.startedAt=Date.now();workshop.finishedAt=null;workshop.message='正在提交';workshop.error=false;workshop.job=null;write('atom.workshopDraft',workshop.prompt);write('atom.workshopJob',null);render();post('/api/workshop/generate',{prompt:prompt,theme_id:workshop.theme_id}).then(function(r){workshop.job={job_id:r.job_id,status:'queued'};write('atom.workshopJob',{id:r.job_id,startedAt:workshop.startedAt});workshop.message='';if(view==='workshop')updateWorkshopProgress();else updateWorkshopBadge();pollJob(r.job_id);}).catch(function(e){workshop.busy=false;workshop.finishedAt=Date.now();workshop.job={status:'failed',error:e.message};workshop.page='failure';workshop.message=e.message;workshop.error=true;if(view==='workshop')render();else updateWorkshopBadge();});}
function pollJob(id){request('/api/workshop/jobs/'+encodeURIComponent(id)).then(function(job){if(!workshop.job||workshop.job.job_id!==id)return;workshop.job=job;workshop.pollFailures=0;workshop.message='';if(job.status==='ready'||job.status==='failed'){workshop.busy=false;workshop.finishedAt=Date.now();workshop.error=job.status==='failed';workshop.page=job.status==='ready'?'celebrate':'failure';workshop.message=job.status==='failed'?safeJobError(job.error):'';if(view==='workshop')render();else updateWorkshopBadge();if(job.status==='ready'){speakFeedback('应用已经生成，请先预览。');}if(job.status==='ready')setTimeout(function(){if(workshop.job&&workshop.job.job_id===id&&workshop.page==='celebrate'){workshop.page='preview';if(view==='workshop'){render();showToast('轻点顶部打开安装操作');}}},experienceAnimations?1100:0);return;}if(view==='workshop')updateWorkshopProgress();else updateWorkshopBadge();workshop.poll=setTimeout(function(){pollJob(id);},1000);}).catch(function(e){if(!workshop.job||workshop.job.job_id!==id)return;if(e.status===404||e.status===400&&e.message==='请求无效或任务不存在'){workshop.pollFailures=0;workshop.finishedAt=Date.now();workshop.busy=false;workshop.job={job_id:id,status:'failed',error:'这个任务已失效，可能是设备服务重启所致。需求草稿还在，可以重新生成。'};workshop.page='failure';workshop.error=true;write('atom.workshopJob',null);if(view==='workshop')render();else updateWorkshopBadge();return;}workshop.pollFailures++;workshop.message='连接暂时中断，正在重新连接';if(view==='workshop')updateWorkshopProgress();workshop.poll=setTimeout(function(){pollJob(id);},Math.min(10000,workshop.pollFailures*2000));});}
function installGenerated(){var job=workshop.job;if(!job||job.status!=='ready'||workshop.busy)return;var updating=apps.some(function(a){return a.id===job.bundle.manifest.id;});if(updating&&!window.confirm('更新桌面上的同名应用？原版本将被替换。'))return;workshop.busy=true;workshop.message='正在安装';render();post('/api/workshop/install',{job_id:job.job_id,update:updating}).then(function(){workshop.busy=false;workshop.installed=true;workshop.page='installed';workshop.message='已安装';speakFeedback('应用已安装到桌面。');workshop.error=false;write('atom.workshopJob',null);return loadApps();}).then(function(){if(view==='workshop')render();}).catch(function(e){workshop.busy=false;workshop.page='result';workshop.message=e.message;workshop.error=true;if(view==='workshop')render();});}
function toggleVoice(){if(workshop.voiceBusy)return;stopSpeech(false);var revision=++workshop.voiceRevision;var recording=workshop.voice&&workshop.voice.recording,pending=workshop.pendingRecordingId;workshop.voiceBusy=true;workshop.page='voice';workshop.voicePhase=recording?'stopping':pending?'transcribing':'starting';workshop.message='';workshop.error=false;render();var action=(recording||pending)?(pending?Promise.resolve({recording_id:pending}):post('/api/voice/stop',{})).then(function(r){workshop.pendingRecordingId=r.recording_id;workshop.voice=workshop.voice||{};workshop.voice.recording=false;updateRecordingIndicator();workshop.voicePhase='transcribing';if(view==='workshop')render();return post('/api/voice/transcribe',{recording_id:r.recording_id});}).then(function(r){if(typeof r.text!=='string'||!r.text.trim())throw Error('没有识别到文字，请输入或重新录音');workshop.pendingRecordingId=null;workshop.prompt+=(workshop.prompt?'\n':'')+r.text;write('atom.workshopDraft',workshop.prompt);workshop.message='';workshop.voicePhase='success';if(view==='workshop'){render();speakFeedback('听到了。你可以修改文字，再生成应用。');}setTimeout(function(){if(workshop.voicePhase==='success'){workshop.voicePhase=null;workshop.page='input';if(view==='workshop')render();}},experienceAnimations?900:0);}):post('/api/voice/start',{quiet_fan:true}).then(function(){workshop.voice=workshop.voice||{};workshop.voice.recording=true;workshop.voicePhase='recording';updateRecordingIndicator();if(view!=='workshop')return post('/api/voice/stop',{}).then(function(r){workshop.pendingRecordingId=r.recording_id;workshop.voice.recording=false;workshop.voicePhase=null;workshop.page='input';updateRecordingIndicator();});});action.catch(function(e){workshop.message=e.message;workshop.error=true;workshop.voicePhase='error';}).then(function(){workshop.voiceBusy=false;if(view==='workshop')render();flushVoiceRelease();request('/api/voice/status').then(function(v){if(revision!==workshop.voiceRevision||workshop.voiceBusy)return;workshop.voice=v;updateRecordingIndicator();if(view==='workshop'&&workshop.page==='voice')render();}).catch(function(){});});}
function workshopClick(b){if(b.dataset.settingsPage){settingsPage=b.dataset.settingsPage;render();return true;}if(b.dataset.workshopPage){workshop.page=b.dataset.workshopPage;render();return true;}if(b.dataset.themeId){themeMessage='正在切换外观';themeError=false;main.querySelectorAll('[data-theme-id]').forEach(function(button){button.disabled=true;});post('/api/themes/activate',{id:b.dataset.themeId}).then(function(){themeMessage='';return loadThemes();}).catch(function(e){themeMessage=e.message;themeError=true;if(view==='themes'||view==='settings')render();});return true;}switch(b.id){case 'permissions-reset':if(write('atom.capabilities.v1',{})){showToast('已撤销应用授权');render();}else showToast('未能保存，请重试');return true;case 'speech-feedback-toggle':speechFeedback=!speechFeedback;write('atom.speechFeedback',speechFeedback);render();return true;case 'speech-open':workshop.page='speak';render();return true;case 'speech-start':speakText(workshop.ttsText,'manual');return true;case 'speech-stop':stopSpeech(true);if(view==='workshop')render();return true;case 'experience-toggle':experienceAnimations=!experienceAnimations;write('atom.experienceAnimations',experienceAnimations);render();return true;case 'voice-cancel':cancelVoice();return true;case 'voice-config':workshop.page='stt';workshop.voicePhase=null;render();return true;case 'workshop-new':workshop.job=null;workshop.prompt='';workshop.installed=false;workshop.page='input';write('atom.workshopDraft','');write('atom.workshopJob',null);render();return true;case 'theme-import':document.getElementById('theme-file').value='';document.getElementById('theme-file').click();return true;case 'model-save':saveModel();return true;case 'workshop-login':navigate('market');return true;case 'workshop-setup':case 'workshop-config':workshop.page='model';render();return true;case 'workshop-regenerate':workshop.page='input';render();return true;case 'workshop-generate':case 'workshop-retry':startGeneration();return true;case 'workshop-install':installGenerated();return true;case 'voice-toggle':toggleVoice();return true;}return false;}
function workshopInput(e){if(e.target.id==='workshop-tts-text'){workshop.ttsText=e.target.value;write('atom.ttsDraft',workshop.ttsText);}if(e.target.id==='workshop-prompt'){workshop.prompt=e.target.value;write('atom.workshopDraft',workshop.prompt);}if(e.target.dataset&&e.target.dataset.modelField){workshop.draft[e.target.dataset.modelField]=e.target.value;workshop.modelTouched=true;}}
function workshopChange(e){if(e.target.id==='model-tts_voice'){workshop.draft.tts_voice=e.target.value;workshop.modelTouched=true;return true;}if(e.target.id==='theme-file'){importTheme(e.target.files[0]);return true;}if(e.target.id==='workshop-theme'){workshop.theme_id=e.target.value;return true;}if(e.target.id==='model-provider'){var p=presetList().find(function(x){return x.id===e.target.value;});workshop.draft.provider=e.target.value;workshop.modelTouched=true;if(p){workshop.draft.base_url=p.base_url||'';workshop.draft.model=p.model||'';workshop.draft.protocol=p.protocol||'openai';}workshop.configOpen=true;render();return true;}return false;}
main.addEventListener('toggle',function(e){if(e.target.id==='model-details')workshop.configOpen=e.target.open;},true);
var recordingIndicator=document.getElementById('recording-indicator');if(recordingIndicator)recordingIndicator.onclick=function(){navigate('workshop');};
