var toastTimeout=null;
function showToast(text){var e=document.getElementById('return-toast');if(!e)return;e.textContent=text;e.hidden=false;if(toastTimeout)clearTimeout(toastTimeout);toastTimeout=setTimeout(function(){e.hidden=true;},3000);}
function showReturnHint(){if(read('atom.returnHint',false))return;write('atom.returnHint',true);showToast('方向键选择 · 空格确认 · 长按空格说话 · 左上角返回');}
function stopRecordingOnLeave(){if(!workshop.voice||!workshop.voice.recording||workshop.voiceBusy)return;workshop.voiceRevision++;workshop.voiceBusy=true;post('/api/voice/stop',{}).then(function(r){workshop.pendingRecordingId=r.recording_id;workshop.voice.recording=false;workshop.voicePhase=null;workshop.page='input';workshop.message='录音已停止，可返回工作坊转写';updateRecordingIndicator();}).catch(function(e){workshop.message=e.message;workshop.error=true;showToast('录音停止失败，请返回工作坊检查');}).then(function(){workshop.voiceBusy=false;});}
var voiceHoldActive=false,voiceReleasePending=false;
function releaseVoice(){if(computerVoice){computerVoice.released=true;finishComputerVoice();return;}if(!voiceHoldActive)return;voiceHoldActive=false;voiceReleasePending=true;flushVoiceRelease();}
function flushVoiceRelease(){if(!voiceReleasePending||workshop.voiceBusy)return;if(workshop.voicePhase==='error'){voiceReleasePending=false;return;}if(workshop.voice&&workshop.voice.recording&&view==='workshop'){voiceReleasePending=false;toggleVoice();}}
function wakeVoice(){if(['my-computer','quick-notes','today','robot','symbiotic-world','language-alchemy','ai-duet','agent-studio','photo-album'].indexOf(view)>=0){wakeComputerVoice();return;}if(workshop.busy){navigate('workshop');return;}voiceHoldActive=true;voiceReleasePending=false;workshop.page='voice';workshop.voicePhase='starting';navigate('workshop');request('/api/voice/status').then(function(v){workshop.voice=v;if(view!=='workshop')return;if(!v.recording)toggleVoice();else{workshop.voicePhase='recording';render();flushVoiceRelease();}}).catch(function(e){workshop.voicePhase='error';workshop.message=e.message;workshop.error=true;if(view==='workshop')render();});}
function handleHomeReturn(){if(officePreviewBack())return;if(pageOverview){closePageOverview();navigate('home');return;}if(appMenu){closeAppMenu();return;}navigate('home');}
window.addEventListener('atom:return-home',handleHomeReturn);
/* Device capability bridge: only the current reviewed computer app receives access. */
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(view!=='my-computer'||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:connect'||typeof d.id!=='string'&&typeof d.id!=='number')return;if(String(d.id).length>128)return;var actions=['state','configure','pair-code','pair-confirm','create-task','task-events','cancel-task','approve-task','artifact','preview-app','install-app'];if(actions.indexOf(d.action)<0)return;var payload=d.data&&typeof d.data==='object'&&!Array.isArray(d.data)?d.data:{};post('/api/connect/'+d.action,payload).then(function(result){if(frame.isConnected&&view==='my-computer'){e.source.postMessage({type:'atom:connect-result',id:d.id,result:result},'*');if(d.action==='preview-app'&&result.bundle){connectPreview=result.bundle;connectPreviewTask=String(payload.task_id||'');navigate('connect-preview');showToast('全屏预览 · 空格返回桌面');}if(d.action==='install-app')loadApps();}}).catch(function(error){if(frame.isConnected&&view==='my-computer')e.source.postMessage({type:'atom:connect-result',id:d.id,error:error.message,status:error.status||0,code:error.code||''},'*');});});
/* Reviewed creative apps receive only their own bounded planner, never model configuration. */
var experienceKinds={'symbiotic-world':'world','language-alchemy':'visual','ai-duet':'duet'};
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe'),kind=experienceKinds[view],originalView=view;if(!kind||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:experience'||['generate','job','cancel'].indexOf(d.action)<0||String(d.id).length>128)return;var payload=d.data&&typeof d.data==='object'&&!Array.isArray(d.data)?Object.assign({},d.data):{};payload.kind=kind;post('/api/experiences/'+d.action,payload).then(function(result){if(frame.isConnected&&view===originalView)e.source.postMessage({type:'atom:experience-result',id:d.id,result:result},'*');}).catch(function(error){if(frame.isConnected&&view===originalView)e.source.postMessage({type:'atom:experience-result',id:d.id,error:error.message},'*');});});
var computerLaunchTask=null;
// Any open app may send the person to a fixed set of system pages; it never receives anything back.
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:go')return;if(d.target==='login'||d.target==='market')navigate('market');else if(d.target==='connect')navigate('my-computer');else if(d.target==='model'){workshop.page='model';navigate('workshop');}else if(d.target==='settings')navigate('settings');});
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(['agent-studio','codex-pet'].indexOf(view)<0||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:agent-studio'||d.action!=='open-computer')return;var taskId=d.data&&d.data.task_id;computerLaunchTask=typeof taskId==='string'&&taskId.length<=128?taskId:'';navigate('my-computer');});
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(view!=='my-computer'||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:computer-launch-ready')return;if(computerLaunchTask!==null){e.source.postMessage({type:'atom:computer-launch',task_id:computerLaunchTask},'*');computerLaunchTask=null;}});
var computerVoice=null;
function computerVoiceState(session,state,text,error){if(session.cancelled||view!==session.view||!session.frame.isConnected)return;session.frame.contentWindow.postMessage({type:session.voiceType,state:state,text:text||'',error:error||''},'*');}
function wakeComputerVoice(){if(computerVoice)return;var frame=main.querySelector('iframe');if(!frame)return;stopSpeech(true);var session={frame:frame,view:view,voiceType:view==='photo-album'?'atom:photo-voice':['symbiotic-world','language-alchemy','ai-duet','agent-studio'].indexOf(view)>=0?'atom:experience-voice':view==='quick-notes'?'atom:notes-voice':view==='today'?'atom:agenda-voice':view==='robot'?'atom:robot-voice':'atom:computer-voice',starting:true,stopping:false,released:false,cancelled:false};computerVoice=session;computerVoiceState(session,'starting');post('/api/voice/start',{quiet_fan:true}).then(function(recording){session.recordingId=recording.recording_id;session.starting=false;if(session.cancelled)return post('/api/voice/stop',{recording_id:session.recordingId});computerVoiceState(session,'recording');if(session.view==='robot')robotMeter(session);if(session.released)finishComputerVoice();}).catch(function(error){computerVoiceState(session,'error','',error.message);if(computerVoice===session)computerVoice=null;});}
function finishComputerVoice(){var session=computerVoice;if(!session||session.starting||session.stopping||session.cancelled)return;session.stopping=true;computerVoiceState(session,'transcribing');post('/api/voice/stop',{recording_id:session.recordingId}).then(function(recording){if(session.cancelled||recording.ignored)return null;return post('/api/voice/transcribe',{recording_id:recording.recording_id});}).then(function(result){if(result)computerVoiceState(session,'done',result.text||'');}).catch(function(error){computerVoiceState(session,'error','',error.message);}).then(function(){if(computerVoice===session)computerVoice=null;});}
function robotMeter(session){if(session.cancelled||session.stopping||computerVoice!==session)return;post('/api/voice/meter',{recording_id:session.recordingId}).then(function(m){if(session.cancelled||session.stopping||view!=='robot'||!session.frame.isConnected)return;session.frame.contentWindow.postMessage({type:'atom:robot-voice',state:'level',level:Math.max(0,Math.min(1,(m.rms_db+55)/40))},'*');}).catch(function(){}).then(function(){setTimeout(function(){robotMeter(session);},120);});}
/* Robot companion bridge: only the reviewed robot app may hold a conversation; credentials stay on the device. */
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(view!=='robot'||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:robot'||['chat','status','stop'].indexOf(d.action)<0||String(d.id).length>128)return;var payload=d.data&&typeof d.data==='object'&&!Array.isArray(d.data)?d.data:{};if(d.action==='chat')stopSpeech(true);post('/api/robot/'+d.action,payload).then(function(result){if(frame.isConnected&&view==='robot')e.source.postMessage({type:'atom:robot-result',id:d.id,result:result},'*');}).catch(function(error){if(frame.isConnected&&view==='robot')e.source.postMessage({type:'atom:robot-result',id:d.id,error:error.message},'*');});});
function cancelComputerVoice(){var session=computerVoice;if(!session)return;session.cancelled=true;session.released=true;if(!session.starting&&!session.stopping)post('/api/voice/stop',{recording_id:session.recordingId}).catch(function(){});computerVoice=null;}

window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if((view!=='mic-test'&&view!=='clap-stage')||!frame||frame.contentWindow!==e.source||!d||d.type!=='atom:mic')return;if(view==='clap-stage'&&['start','stop','meter'].indexOf(d.action)<0)return;var micView=view;var routes={start:'start',stop:'stop',meter:'meter',play:'play-recording',quiet:'playback-stop',fan:'fan'};if(!routes[d.action])return;post('/api/voice/'+routes[d.action],{recording_id:d.recording_id,action:d.fan_action,quiet_fan:micView==='clap-stage'}).then(function(r){if(view===micView&&frame.isConnected)e.source.postMessage({type:'atom:mic-result',id:d.id,result:r},'*');else if(d.action==='start')post('/api/voice/stop',{}).catch(function(){});else if(d.action==='play')post('/api/voice/playback-stop',{}).catch(function(){});else if(d.action==='fan'&&d.fan_action==='off')post('/api/voice/fan',{action:'auto'}).catch(function(){});}).catch(function(err){if(frame.isConnected)e.source.postMessage({type:'atom:mic-result',id:d.id,error:err.message},'*');});});

/* One owner per joystick dictation; all audio stays in the trusted shell. */
var inputVoice=null;
function inputVoiceStatus(text){var el=document.getElementById('atom-input-voice-status');if(!text){if(el)el.remove();return;}if(!el){el=document.createElement('div');el.id='atom-input-voice-status';el.setAttribute('role','status');el.style.cssText='position:fixed;bottom:12px;left:50%;transform:translateX(-50%);z-index:2147483646;padding:10px 16px;border-radius:18px;background:var(--card,#fff);color:var(--ink,#111);box-shadow:0 4px 24px #0003;pointer-events:none;white-space:nowrap';document.body.appendChild(el);}el.textContent=text;}

function inputVoiceReply(session,data){var payload=Object.assign({type:'atom:input-voice-result',request_id:session.id},data);if(session.frame){if(session.frame.isConnected&&main.querySelector('iframe')===session.frame)session.frame.contentWindow.postMessage(payload,'*');}else window.dispatchEvent(new CustomEvent(payload.type,{detail:payload}));}
function inputVoiceFinish(session){if(inputVoice!==session||session.starting||session.stopping)return;session.stopping=true;inputVoiceStatus(session.cancelled?'正在取消录音…':'正在识别…');post('/api/voice/stop',{recording_id:session.recordingId}).then(function(r){if(r.ignored)throw Error('录音会话已改变');if(session.cancelled)return null;return post('/api/voice/transcribe',{recording_id:r.recording_id});}).then(function(r){if(r&&!session.cancelled){inputVoiceReply(session,{text:r.text||''});if(!r.text||!r.text.trim())showToast('没有识别到文字');}else inputVoiceReply(session,{error:'录音已取消'});}).catch(function(e){inputVoiceReply(session,{error:e.message});showToast(e.message);}).then(function(){if(inputVoice===session){inputVoice=null;inputVoiceStatus('');}});}
function inputVoiceStart(d,frame){if(d.mode!=='dictation'){wakeVoice();return;}if(inputVoice||computerVoice||workshop.voiceBusy||workshop.voice&&workshop.voice.recording){if(frame)frame.contentWindow.postMessage({type:'atom:input-voice-result',request_id:d.request_id,error:'已有录音任务，请稍后重试'},'*');else AtomInput.receive({type:'atom:input-voice-result',request_id:d.request_id,error:'已有录音任务'});showToast('已有录音任务，请稍后重试');return;}stopSpeech(true);var session={id:d.request_id,frame:frame,view:view,starting:true,stopping:false,released:false,cancelled:false};inputVoice=session;inputVoiceStatus('正在开启麦克风…');post('/api/voice/start',{quiet_fan:true}).then(function(r){session.recordingId=r.recording_id;session.starting=false;if(session.view!==view||session.frame&&!session.frame.isConnected)session.cancelled=true;inputVoiceStatus('● 正在收音 · 松开结束');if(session.released||session.cancelled)inputVoiceFinish(session);}).catch(function(e){inputVoiceReply(session,{error:e.message});if(inputVoice===session){inputVoice=null;inputVoiceStatus('');}showToast(e.message);});}
function inputVoiceRelease(d){if(inputVoice&&inputVoice.id===d.request_id){inputVoice.released=true;inputVoice.cancelled=inputVoice.cancelled||!!d.cancel;inputVoiceFinish(inputVoice);}else releaseVoice();}
window.addEventListener('atom:input-voice-start',function(e){inputVoiceStart(e.detail,null);});
window.addEventListener('atom:input-voice-release',function(e){inputVoiceRelease(e.detail);});
window.addEventListener('message',function(e){var d=e.data,frame=main.querySelector('iframe');if(!d||!frame||frame.contentWindow!==e.source||typeof d.request_id!=='string'||d.request_id.length>100)return;if(d.type==='atom:input-voice-start')inputVoiceStart(d,frame);else if(d.type==='atom:input-voice-release')inputVoiceRelease(d);});
function joystickBack(){if(pageOverview){closePageOverview();return;}if(appMenu){closeAppMenu();return;}if(view==='settings'&&settingsPage!=='menu'){settingsPage=['permissions','sorting'].indexOf(settingsPage)>=0?'personal':'menu';render();return;}if(view==='workshop'&&workshop.page!=='input'&&!workshop.busy){stopRecordingOnLeave();workshop.page='input';render();return;}navigate('home');}
