function workshopBadge(){return workshop.busy?(workshop.job&&workshop.job.status==='ready'?'安装中':'生成中'):workshop.job&&workshop.job.status==='ready'&&!workshop.installed?'待预览':workshop.job&&workshop.job.status==='failed'?'需重试':'';}
function updateWorkshopBadge(){if(view==='home'){var element=main.querySelector('[data-app="workshop"]');if(element)element.outerHTML=tile(builtin.find(function(a){return a.id==='workshop';}));}}
function appFrameHtml(name,entry,preview){return '<div class="app-stage"><iframe '+(preview?'id="workshop-preview"':'src="'+esc(entry)+'"')+' sandbox="allow-scripts" title="'+esc(name)+'"></iframe><section id="launch-screen" class="launch-screen" data-state="loading" role="status"><div class="launch-mark"><span class="launch-pulse"></span></div><h1>'+esc(name)+'</h1><p id="launch-message">正在打开</p><div id="launch-actions" class="workshop-actions" hidden><button id="launch-retry" class="primary">重新打开</button><button id="launch-home">返回桌面</button></div></section></div>';}
var launchRevision=0,launchFade=null;
function updateLaunch(state){var el=document.getElementById('launch-screen');if(!el)return;var revision=++launchRevision;clearTimeout(launchFade);el.dataset.state=state;var stage=el.parentElement;stage.dataset.launch=state;el.hidden=false;var message=document.getElementById('launch-message'),actions=document.getElementById('launch-actions');message.textContent={loading:'正在打开',delayed:'启动还没完成，可以继续等待或重新打开。',failed:'应用没能正常启动，可以重新打开。'}[state]||'';actions.hidden=state==='loading'||state==='ready';if(state==='ready'){requestAnimationFrame(function(){requestAnimationFrame(function(){if(revision!==launchRevision||!el.isConnected)return;el.classList.add('launch-complete');launchFade=setTimeout(function(){if(el.isConnected&&revision===launchRevision)el.hidden=true;},160);});});}else el.classList.remove('launch-complete');if(state==='failed'||state==='delayed'){document.getElementById('launch-retry').onclick=function(){render();};document.getElementById('launch-home').onclick=handleHomeReturn;}}

function companionHtml(state,size){return experienceAnimations?'<canvas class="system-companion '+(size||'')+'" data-companion="'+state+'" aria-label="'+({listening:'正在倾听',thinking:'正在思考',success:'开心',speaking:'正在说话',error:'遇到问题',idle:'等待操作'}[state]||state)+'"></canvas>':'';}
function syncCompanion(){var c=main.querySelector('[data-companion]');if(c&&experienceAnimations)systemCompanion=AtomCompanion(c,c.dataset.companion);}
function voiceHtml(){var phase=workshop.voicePhase||'recording',busy=workshop.voiceBusy,recording=workshop.voice&&workshop.voice.recording;var state=workshop.speechStatus==='speaking'?'speaking':phase==='success'?'success':phase==='error'?'error':phase==='transcribing'||phase==='starting'||phase==='stopping'?'thinking':'listening';var title={starting:'准备听你说',recording:'我在听',stopping:'正在结束录音',transcribing:'把声音变成文字',recorded:'录音已完成',success:'听懂了',error:'语音暂不可用'}[phase]||'我在听';return '<div class="flow-screen voice-surface" data-state="'+state+'"><div class="voice-orb" aria-hidden="true"><span></span></div><div class="voice-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><h1>'+title+'</h1><p class="flow-detail atom-scroll">'+esc(workshop.message||(phase==='recording'?'按住空格说话，松开后自动转写。':phase==='transcribing'?'正在使用配置的语音转写服务。':'可以随时返回文字编辑。'))+'</p><div class="workshop-actions"><button id="voice-toggle" class="primary" '+(busy||phase==='success'?'disabled':'')+'>'+(recording?'停止并转写':workshop.pendingRecordingId?'重试转写':'重新录音')+'</button><button id="voice-cancel" '+(busy?'disabled':'')+'>文字输入</button>'+(phase==='error'?'<button id="voice-config" '+(recording?'disabled':'')+'>转写配置</button>':'')+'</div></div>';}
function cancelVoice(){if(workshop.voiceBusy)return;stopSpeech(false);workshop.voiceRevision++;workshop.voiceBusy=true;var stop=workshop.voice&&workshop.voice.recording?post('/api/voice/stop',{}):Promise.resolve();stop.then(function(){workshop.voice=workshop.voice||{};workshop.voice.recording=false;workshop.voicePhase=null;workshop.pendingRecordingId=null;workshop.page='input';workshop.message='';workshop.error=false;updateRecordingIndicator();}).catch(function(e){workshop.message=e.message;workshop.error=true;}).then(function(){workshop.voiceBusy=false;if(view==='workshop')render();});}
function pollVoiceStatus(){if(!workshop.voice||!workshop.voice.recording||workshop.voiceBusy)return;var revision=workshop.voiceRevision;request('/api/voice/status').then(function(v){if(revision!==workshop.voiceRevision||workshop.voiceBusy)return;var stopped=workshop.voice.recording&&!v.recording;workshop.voice=v;if(stopped){workshop.pendingRecordingId=v.recording_id;workshop.voicePhase='recorded';workshop.message='录音已自动停止，点击转写录音';}updateRecordingIndicator();if(stopped&&view==='workshop')render();}).catch(function(){});}

function speechHtml(){var active=workshop.speechBusy||['generating','speaking'].indexOf(workshop.speechStatus)>=0;if(active)return '<div class="flow-screen">'+companionHtml(workshop.speechStatus==='speaking'?'speaking':'thinking')+'<h1>'+(workshop.speechStatus==='speaking'?'正在朗读':'正在准备语音')+'</h1><p class="flow-detail atom-scroll">'+esc(workshop.ttsText)+'</p><div class="workshop-actions"><button id="speech-stop">停止朗读</button></div></div>';return '<div class="page-heading"><h1>文字朗读</h1><button data-workshop-page="tts">语音配置</button></div><textarea id="workshop-tts-text" maxlength="1024" aria-label="朗读内容" placeholder="输入想让设备说的话">'+esc(workshop.ttsText)+'</textarea><div class="workshop-actions"><button id="speech-start" class="primary">朗读</button></div><p class="feedback '+(workshop.speechError?'error':'')+'">'+esc(workshop.speechError||(workshop.speechStatus==='done'?'朗读完成':'最多 1024 字 · 空格返回会停止朗读'))+'</p>';}
