function speakFeedback(text){if(speechFeedback&&view==='workshop'&&workshop.config&&(workshop.config.tts_api_key_set||workshop.voice&&workshop.voice.tts_configured||workshop.config.official&&workshop.config.official.active))speakText(text,'feedback');}
